- (const char *)windowTitle;
	{
	char 		adj[8][12]={"amazing","astonishing","astounding","awesome",
					"marvelous","stupendous","spectacular","wonderful"};
	static char buf[50];
	
	srandom(clock());
	sprintf(buf,"%s arabesque patterns",adj[random()%8]);
	return buf;
	}
	

- oneStep
	{
	int		da[10]={0,0,1,1,7,7,2,6,3,5};
	int 	i,compOp=NX_SOVER;
	NXCoord	k,l,r,x,y,xp,yp;
	NXRect	cRect={-1,-1,2,2};
	
	PSnewpath();
	PSmoveto( 1, 1); PSlineto(-1, 1); PSlineto(-1,-1); PSlineto( 1,-1);
	PSclosepath();
	PSclip();

	if(random()%clearProb==0)
		{
		PSsetgray(0);
		NXRectFill(&cRect);
		clearProb=INITIAL_CLEAR_PROB;
		copyProb=(random()%copyProb)?INITIAL_COPY_PROB:1;
		}
	else
		{
		NXSetColor(NXConvertHSBToColor((random()%100)*0.01,
						(random()%10)*0.01+0.9,(random()%30)*0.01+0.7));
//		PSsetgray((random()%80)*0.01+0.2);
		PSsetlinewidth((random()%LINE_WIDTH_FACTOR)*MIN_LINE_WIDTH);
		switch(r2fx[random()%100])
			{
		case 1:
			l=LINE_SEGMENT_LENGTH;
			k=sqrt(2*l*l);
			x=random()%100*0.001;
			y=random()%100*0.001;
			for(i=1;x<1 && y<1 && i<20;i++)
				{
				xp=x; yp=y;
				switch(da[random()%10])
					{
				case 0:	x+=k; y+=k;	break;
				case 1:		  y+=l;	break;
				case 2: x-=k; y+=k;	break;
				case 3:	x-=l;		break;
				case 4:	x-=k; y-=k; break;
				case 5:		  y-=l;	break;
				case 6: x+=k; y-=k;	break;
				case 7: x+=l;		break;
					}
				PSanimline(xp,yp,x,y);
				}
			clearProb-=20;
			break;
		case 2:
			x=y=0;
			r=(random()%50+50)*0.01;
			PSanimcircle(x,y,r);
			clearProb-=5;
			break;
		case 3:
			x=y=(random()%50+20)*0.01;
			r=random()%100*0.01*(1-x);
			PSanimcircle(x,y,r);
			clearProb-=5;
			}
		clearProb=MAX(3,clearProb);
		copyProb=MAX(2,copyProb-20);
		}

	PSinitclip();
	if((random()%copyProb)==0)
		if(random()%2)
			{
			PScomposite(-1,-1,2,2,NXNullObject,-3, 1,compOp);
			PScomposite(-1,-1,2,2,NXNullObject,-3,-3,compOp);
			PScomposite(-1,-1,2,2,NXNullObject, 1,-3,compOp);
			PScomposite(-1,-1,2,2,NXNullObject, 1, 1,compOp);
			copyProb=INITIAL_COPY_PROB;
			}
		else
			{
			PScomposite(-1,-1,2,2,NXNullObject,-1,-3,compOp);
			PScomposite(-1,-1,2,2,NXNullObject, 1,-1,compOp);
			PScomposite(-1,-1,2,2,NXNullObject,-1, 1,compOp);
			PScomposite(-1,-1,2,2,NXNullObject,-3,-1,compOp);
			copyProb=INITIAL_COPY_PROB;
			}
		
	return self;
	}


- initFrame:(const NXRect *)frameRect;
	{
	int		r[5]={0,80,6,14,0};
	int		i,j,ai;
	
	[super initFrame:frameRect];
	[self setDrawSize:6*frame.size.width/frame.size.height:6];
	[self translate:3*frame.size.width/frame.size.height:3];
	erased=NO;
	clearProb=INITIAL_CLEAR_PROB;
	copyProb=INITIAL_COPY_PROB;
	for(j=0,ai=0;j<5;j++)
		for(i=0;i<r[j];i++)
			r2fx[ai++]=j;

	return self;
	}


- sizeTo:(NXCoord)width :(NXCoord)height;
	{
	[super sizeTo:width:height];
	[self setDrawSize:6*frame.size.width/frame.size.height:6];
	[self setDrawOrigin:-3*frame.size.width/frame.size.height:-3];
	erased=NO;
	[self display];
	return self;
	}

		
- drawSelf:(const NXRect *)rects :(int)rectCount;
	{
	if(!erased)
		{
		PSsetgray(0);
		NXRectFill(&bounds);
		erased=YES;
		}
	return self;
	}



